//! The ported document checks, one module per ticket script.
//!
//! Each module `c<id>` (file `c<id>.rs` or directory `c<id>/`) holds the
//! check of `checks/<id>.sh` as a function from [`Docs`] to [`Report`], and a
//! [`CheckSpec`] named `SPEC` that tells the equivalence harness how to
//! compare it with its script. The registry is generated by `build.rs` from
//! this directory: adding a port never edits a shared file.

use super::Docs;
use super::Report;
use super::denial::Denial;
use super::policy::TomlReader;

/// What the equivalence harness needs to know about one port.
#[derive(Debug)]
pub struct CheckSpec {
    /// The ticket id, as in `checks/<id>.sh`.
    pub id: &'static str,
    /// The port. Called only by [`CheckSpec::evaluate`] (which guards what
    /// it reads and turns regex engine failures red); a source test forbids
    /// any other call.
    pub(crate) run: fn(&Docs) -> Report,
    /// Environment the script must get under the harness: the override
    /// variables it honours, set to the exported copies, so it skips its
    /// repository-level cargo runs (those moved to
    /// `scripts/repo-state-checks.sh`). Paths are relative to the export
    /// root, which is the script's working directory.
    pub script_env: &'static [(&'static str, &'static str)],
    /// The documents and sections the mutation corpus edits.
    pub targets: &'static [Target],
    /// Words whose negation the corpus tries, beyond the defaults.
    pub keywords: &'static [&'static str],
    /// The verdict differences that are understood, with their reason.
    pub known_differences: &'static [KnownDifference],
    /// The check's denial list: run by its tests and, with `--denials`, by
    /// the harness against the old script.
    pub denials: &'static [Denial],
    /// The TOML reader the script used.
    pub toml: TomlReader,
}

/// A section of a document the corpus mutates.
#[derive(Debug, Clone, Copy)]
pub struct Target {
    /// Repository-relative path.
    pub file: &'static str,
    /// A heading pattern (regex): the first match's section is mutated;
    /// `None` for the whole file.
    pub heading: Option<&'static str>,
}

/// The class of an understood difference, with the direction it may
/// excuse (see [`DiffKind`]). "Port weaker" is never a class: a script red
/// that the port does not match fails the harness, with the one exception
/// the lead ruled (R3) for the subset TOML reader rejecting valid TOML.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffClass {
    /// The port rejects what the script accepted, for the stated reason.
    PortStricter,
    /// The port's typed TOML parser rejects a value the script's reader let
    /// through (`dscp = 40.0` compares equal to 40 in Python).
    PortStricterTyped,
    /// The script's verdict is wrong; the reason says how.
    ScriptWrong,
    /// The script's hand-written subset TOML reader rejected valid TOML
    /// (`note = """…"""`) and no assertion of the script was aimed at it.
    SubsetTomlReader,
    /// The script crashed (a traceback, no FAIL line) on input the port
    /// reports as a failure.
    ScriptCrashed,
    /// An input holds a character outside the repertoire: the port is red by
    /// rule. Applied by the harness itself whenever the port reports
    /// `REPERTOIRE`; never listed in `KNOWN`.
    OutsideRepertoire,
    /// The port's regex engine failed (backtracking limit, refused
    /// pattern): the port is red by rule ("port stricter (regex limit)",
    /// R19). Applied by the harness itself whenever the port reports
    /// `REGEX_LIMIT`; never listed in `KNOWN`.
    RegexLimit,
}

/// How the two verdicts differ.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffKind {
    /// The script fails, the port passes.
    ScriptRedPortPass,
    /// The script passes, the port fails.
    ScriptPassPortRed,
    /// Both fail; the port fails every criterion the script failed, and more.
    PortMoreCriteria,
    /// Both fail; the script failed a criterion the port did not.
    PortMissingCriteria,
    /// The script crashed; the port fails.
    ScriptCrashPortRed,
    /// The script crashed; the port passes.
    ScriptCrashPortPass,
    /// The script was still running at the harness's timeout; the port fails.
    ScriptTimedOutPortRed,
    /// The script was still running at the harness's timeout; the port
    /// passes (nothing can be compared: never excused).
    ScriptTimedOutPortPass,
}

impl DiffKind {
    /// True when this kind, unexcused, makes the port weaker.
    pub fn weaker(self) -> bool {
        matches!(
            self,
            DiffKind::ScriptRedPortPass
                | DiffKind::PortMissingCriteria
                | DiffKind::ScriptCrashPortPass
                | DiffKind::ScriptTimedOutPortPass
        )
    }

    /// True when `class` may excuse a difference of this kind.
    pub fn excused_by(self, class: DiffClass) -> bool {
        use DiffClass::*;
        let by_kind = match self {
            DiffKind::ScriptRedPortPass | DiffKind::ScriptCrashPortPass => {
                class == SubsetTomlReader
            }
            DiffKind::ScriptPassPortRed => {
                matches!(class, PortStricter | PortStricterTyped | ScriptWrong)
            }
            DiffKind::PortMoreCriteria => {
                matches!(class, PortStricter | PortStricterTyped | ScriptWrong)
            }
            DiffKind::PortMissingCriteria => matches!(class, ScriptWrong | SubsetTomlReader),
            DiffKind::ScriptCrashPortRed => class == ScriptCrashed,
            DiffKind::ScriptTimedOutPortRed | DiffKind::ScriptTimedOutPortPass => false,
        };
        by_kind
            || (matches!(class, OutsideRepertoire | RegexLimit) && !self.weaker_if_port_passes())
    }

    /// True for the kinds where the port passes (no rule makes those red).
    fn weaker_if_port_passes(self) -> bool {
        matches!(
            self,
            DiffKind::ScriptRedPortPass
                | DiffKind::ScriptCrashPortPass
                | DiffKind::ScriptTimedOutPortPass
        )
    }
}

/// One understood difference: mutations or denials whose label matches
/// `label` (a regex), excused by `class` when the class fits the kind of
/// difference, for the stated reason.
#[derive(Debug, Clone, Copy)]
pub struct KnownDifference {
    pub label: &'static str,
    pub class: DiffClass,
    pub reason: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/checks_registry.rs"));

/// The port of `id`, if one is registered.
pub fn find(id: &str) -> Option<&'static CheckSpec> {
    registry().into_iter().find(|s| s.id == id)
}

#[cfg(test)]
mod tests {
    /// The real documents with one local corruption each, so the deep paths
    /// behind a real probe section and a real traceability table run (review
    /// round 2, e).
    #[test]
    fn no_check_panics_on_real_documents_with_one_corruption() {
        let big = "9".repeat(60);
        let base = crate::doccheck::testing::repo().clone();
        let md = |old: &str, new: String| -> Box<dyn Fn(&str) -> String + 'static> {
            let old = old.to_string();
            Box::new(move |t: &str| t.replacen(&old, &new, 1))
        };
        type Edit = Box<dyn Fn(&str) -> String>;
        let cases: Vec<(&str, Edit)> = vec![
            ("doc/design/spec/wire.md", md("| 52 | 2 | u16 | Intended packet size", format!("| 52 | {big} | u16 | Intended packet size"))),
            ("doc/design/spec/wire.md", md("| 54 | 1 × max 65453 |", format!("| {big} | 1 × max {big} |"))),
            ("doc/design/spec/wire.md", md("| Rule 7 |", format!("| Rule {big} |"))),
            ("doc/design/spec/wire.md", md("| C-122 |", format!("| C-{big} |"))),
            ("doc/design/spec/wire.md", md("The reply's maximum size is 54 bytes", format!("The reply's maximum size is {big} bytes"))),
            ("doc/design/spec/wire.md", md("### Path-MTU probe request", "#".to_string())),
            ("doc/design/spec/wire.toml", md("offset = 384", "offset = 9223372036854775807\nwidth = 9223372036854775807\nmax_count = 9223372036854775807".into())),
            ("doc/design/spec/wire.toml", md("max_size = 65507", format!("max_size = {big}"))),
            ("doc/design/spec/wire.toml", md("dscp = 40", "field = \"x\"\nrejection_reasons = 7".into())),
            ("doc/design/spec/wire.toml", md("[[message.field]]", "[[message.field]]\nname = [1]".into())),
            ("doc/design/02-constants.md", md("1 280 bytes", format!("{big} bytes"))),
        ];
        for spec in super::registry() {
            for (file, edit) in &cases {
                let docs = base.mutate(file, |t| edit(t));
                let outcome =
                    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| spec.evaluate(&docs)));
                assert!(
                    outcome.is_ok(),
                    "{} panicked on a corrupted {file}",
                    spec.id
                );
            }
        }
    }

    /// Lead ruling R8: a check reports, never panics, on malformed input.
    #[test]
    fn no_check_panics_on_malformed_input() {
        let big = "9".repeat(60);
        let wire_md = [
            String::new(),
            "|".into(),
            "#".into(),
            "# Foo (x\n## Traceability table\n| Rule 1 | (x |\n|---|\n| 1 |".into(),
            format!(
                "## Path-MTU probe pair\n### Path-MTU probe request\n| Offset | Width | Type | Meaning | Valid |\n|---|---|---|---|---|\n| {big} | {big} × max {big} | u8 | Message type {big} | {big} |\nmaximum size {big} bytes"
            ),
            "a\u{2028}### x\u{0c}| a |\r\n|---|\r| b |".into(),
        ];
        let wire_toml = [
            String::new(),
            "[[".into(),
            "message = 5".into(),
            "refusal = [{ name = [1], value = 1 }]".into(),
            "[[message]]\nname = \"path-MTU probe request\"\nfield = \"abc\"\nrejection_reasons = 7".into(),
            "[[message]]\nname = \"path-MTU probe reply\"\nmax_size = 9223372036854775807\n[[message.field]]\nname = \"a\"\noffset = 9223372036854775807\nwidth = 9223372036854775807\nmax_count = 9223372036854775807".into(),
            "[[message]]\n[[message.field]]\nwidth = 1".into(),
        ];
        let constants = format!("| C-06 | x | {big} |\n| C-17 | x | at most {big} bytes |");
        let base = crate::doccheck::testing::repo().clone();
        for spec in super::registry() {
            for md in &wire_md {
                for t in &wire_toml {
                    let docs = base
                        .with("doc/design/spec/wire.md", md.clone())
                        .with("doc/design/spec/wire.toml", t.clone())
                        .with("doc/design/02-constants.md", constants.clone());
                    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        spec.evaluate(&docs)
                    }));
                    assert!(
                        outcome.is_ok(),
                        "{} panicked on wire.md {md:?} and wire.toml {t:?}",
                        spec.id
                    );
                }
            }
        }
    }
}
